  NumericUtils.intToSortableBytes(maxX, bytes, 3 * BYTES);
  NumericUtils.intToSortableBytes(y, bytes, 4 * BYTES);
  NumericUtils.intToSortableBytes(x, bytes, 5 * BYTES);
